import {test} from 'node:test';
import assert from 'node:assert/strict';
import {validateBrowserSource} from './resignation-browser.mjs';
import {validateResignationFixture,REQUIRED_RESIGNATION_CAPTURES} from '../../scripts/resignation-browser-acceptance.mjs';
const sha='a'.repeat(40),env={GITHUB_ACTIONS:'true',CI:'true',RUNNER_ENVIRONMENT:'github-hosted',GITHUB_REPOSITORY:'StradaverseHub/ai-hr',AIHR_CI_HEAD:sha,AIHR_CI_CONTROL_HEAD:'b'.repeat(40)};
const id=n=>`10000000-0000-4000-8000-${String(n).padStart(12,'0')}`;
const prepared=()=>{const actors=['configurer','manager','gbs','ceo','bp','accept','retain','decline','recall','unconfigured','outsider'].map((key,index)=>({key,userId:id(index+20),personId:key==='configurer'?null:id(index+40)}));return{preparationOnly:true,reused:false,cases:{accept:[],retain:[],decline:[],recall:[],unconfigured:[]},fixture:{version:2,tenantId:id(1),companyId:id(2),groupId:id(3),normalDepartmentId:id(60),gapDepartmentId:id(61),repairWorkflowId:id(62),acceptanceLetterName:'Resignation acceptance letter',retentionLetterName:'Retention offer e-letter',privateSentinel:'RJ_BROWSER_PRIVATE_93017',workflowIds:Array.from({length:11},(_,index)=>id(index+4)),actors,roleBindings:['gbs','ceo','bp'].map((role,index)=>({role,userId:actors.find(actor=>actor.key===role).userId,groupId:id(index+70),...(role!=='gbs'?{routingId:id(index+80)}:{})}))}};};
test('requires the exact clean hosted candidate without installation auth or seed override',()=>{assert.doesNotThrow(()=>validateBrowserSource(env,sha,''));for(const changed of [{GITHUB_ACTIONS:'false'},{RUNNER_ENVIRONMENT:'self-hosted'},{AIHR_CI_HEAD:'c'.repeat(40)},{AUTH_PROVIDER:'internal'},{SEED_MAY_DESTROY_OTHER_TENANTS:'true'}])assert.throws(()=>validateBrowserSource({...env,...changed},sha,''));assert.throws(()=>validateBrowserSource(env,sha,' M app/page.tsx'));});
test('validates actual fixture identity before allowing screenshot evidence',()=>{assert.equal(validateResignationFixture(prepared()).version,2);for(const change of [value=>value.fixture.actors.pop(),value=>value.fixture.actors[1].userId=value.fixture.actors[0].userId,value=>value.fixture.workflowIds=[],value=>value.cases.accept=[{id:id(40)}],value=>value.preparationOnly=false]){const value=prepared();change(value);assert.throws(()=>validateResignationFixture(value));}});
test('requires distinct rendered coverage across configuration, actors, decisions, letters and Personnel outcomes',()=>{assert.equal(new Set(REQUIRED_RESIGNATION_CAPTURES).size,REQUIRED_RESIGNATION_CAPTURES.length);for(const required of ['configuration-document-editor','configuration-email-editor','bp-fyi','employee-sign','declined-offer','recalled-letter','clearance-posting','outsider-denied'])assert(REQUIRED_RESIGNATION_CAPTURES.includes(required));});

test('final review packet requires owner regeneration, linked acceptance PDF and four mobile captures across three actor classes',()=>{for(const required of ['owner-regenerated-letter','linked-acceptance-documents','linked-acceptance-pdf','employee-submit-mobile','employee-tracking-mobile','manager-decision-mobile','configuration-decision-mobile'])assert(REQUIRED_RESIGNATION_CAPTURES.includes(required));assert.equal(REQUIRED_RESIGNATION_CAPTURES.filter(id=>id.endsWith('-mobile')).length,4);});

test('final fixture requires actual GBS, CEO and BP identities, distinct repair department and default signer captures',()=>{for(const required of ['bp-sign-acceptance','ceo-sign-retention','unconfigured-employee-recorded','unconfigured-gbs-repair','repaired-decision-assigned'])assert(REQUIRED_RESIGNATION_CAPTURES.includes(required));for(const change of [value=>value.fixture.roleBindings.pop(),value=>value.fixture.roleBindings[0].userId=id(999),value=>value.fixture.gapDepartmentId=value.fixture.normalDepartmentId,value=>value.fixture.actors.find(actor=>actor.key==='ceo').personId=null]){const value=prepared();change(value);assert.throws(()=>validateResignationFixture(value));}});
